<script lang="ts">
	import { enhance } from '$app/forms';
	import { hasErrors, readContact, validateContact, type ContactErrors } from '#lib/contact.js';
	import type { PageProps } from './$types';
	import type { SubmitFunction } from '@sveltejs/kit';

	let { form }: PageProps = $props();

	// Errors found in the browser; `null` defers to the server's answer.
	let clientErrors = $state<ContactErrors | null>(null);

	const errors = $derived<ContactErrors>(clientErrors ?? form?.errors ?? {});
	const values = $derived(form?.values);
	const success = $derived(clientErrors === null && form?.success ? form.name : null);

	const submit: SubmitFunction = ({ formData, cancel }) => {
		const found = validateContact(readContact(formData));
		if (hasErrors(found)) {
			clientErrors = found;
			cancel();
			return;
		}
		clientErrors = null;
	};
</script>

<svelte:head>
	<title>Contact | Bookshelf</title>
</svelte:head>

<h1>Contact</h1>

{#if success !== null}
